# Atama Problemi - PuLP
from pulp import *

kisiler = ['Elif', 'Berk', 'Cansu']
görevler = ['A', 'B', 'C']
maliyet = {
    'Elif':  {'A': 9, 'B': 2, 'C': 7},
    'Berk':  {'A': 3, 'B': 6, 'C': 4},
    'Cansu': {'A': 1, 'B': 5, 'C': 8}
}

prob = LpProblem('Atama', LpMinimize)
x = {(i,j): LpVariable(f'x_{i}_{j}', cat='Binary')
     for i in kisiler for j in görevler}

# Amaç fonksiyonu
prob += lpSum(maliyet[i][j]*x[i,j] for i in kisiler for j in görevler)

# Her kişi 1 görev
for i in kisiler:
    prob += lpSum(x[i,j] for j in görevler) == 1

# Her görev 1 kişi
for j in görevler:
    prob += lpSum(x[i,j] for i in kisiler) == 1

prob.solve(PULP_CBC_CMD(msg=0))
print(f'Minimum Maliyet: {value(prob.objective)}')
for i in kisiler:
    for j in görevler:
        if x[i,j].value() == 1:
            print(f'  {i} → Proje {j}')
